using JewelDesign.Documents;
using JewelDesign.Features.Candidate;
using JewelDesign.Geometry.Candidate;
namespace CandidateGeometryContractChecks;
internal static class SewingAssertions
{
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static void Throws<T>(Action action)where T:Exception{try{action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
 static CandidateShape Face(CandidateContext context,params CandidatePoint3[] poles)=>context.CreateNurbsSurface(new(1,1,2,2,poles,new[]{0.0,0,1,1},new[]{0.0,0,1,1}),1e-8);
 public static string Run(){using var context=CandidateContext.Create();int cases=0;CandidateShape retained;
  using(var a=Face(context,new(0,0,0),new(0,1,0),new(1,0,0),new(1,1,0)))using(var b=Face(context,new(1,0,0),new(1,1,0),new(2,0,0),new(2,1,0))){var before=context.GetShapeBounds(a,CandidateShapeBoundsMode.Fast);using var joined=context.SewBreps(new[]{a,b},.01);Check(context.GetShapeBounds(a,CandidateShapeBoundsMode.Fast)==before,"Sewing changed original topology/tolerance bounds");Check(Math.Abs(joined.Info.NativeTolerance-.01)<1e-15&&joined.Info.Parts==1&&joined.Info.Faces==2&&joined.Info.ContiguousEdges==1&&joined.Info.FreeEdges==6,"Adjacent native faces not sewed");Check(context.Inspect(joined.Shape).IsValid,"Sewed faces invalid");retained=context.Retain(joined.Shape);using var far=context.Translate(b,10,0,0);using var disjoint=context.SewBreps(new[]{a,far},.01);Check(disjoint.Info.Parts==2&&disjoint.Info.Faces==2&&disjoint.Info.ContiguousEdges==0,"Disconnected faces reported joined");cases+=2;}
  using(retained)Check(context.Inspect(retained).IsValid,"Sewed result lost geometry after input/result owners disposed");
  using(var a=Face(context,new(0,0,0),new(0,1,0),new(1,0,0),new(1,1,0)))using(var b=Face(context,new(1.001,0,0),new(1.001,1,0),new(2,0,0),new(2,1,0))){var before=context.GetShapeBounds(a,CandidateShapeBoundsMode.Fast);using var tight=context.SewBreps(new[]{a,b},1e-5);using var loose=context.SewBreps(new[]{a,b},.01);Check(tight.Info.Parts==2&&loose.Info.Parts==1,"Explicit native sewing tolerance ignored");Check(context.GetShapeBounds(a,CandidateShapeBoundsMode.Fast)==before,"Loose sewing mutated original input tolerance");cases+=2;}

  var faces=new[]{
   Face(context,new(0,0,0),new(0,3,0),new(0,0,4),new(0,3,4)),Face(context,new(2,0,0),new(2,0,4),new(2,3,0),new(2,3,4)),
   Face(context,new(0,0,0),new(0,0,4),new(2,0,0),new(2,0,4)),Face(context,new(0,3,0),new(2,3,0),new(0,3,4),new(2,3,4)),
   Face(context,new(0,0,0),new(2,0,0),new(0,3,0),new(2,3,0)),Face(context,new(0,0,4),new(0,3,4),new(2,0,4),new(2,3,4))};
  try{using var shell=context.SewBreps(faces,.01);Check(shell.Info.Parts==1&&shell.Info.Faces==6&&shell.Info.FreeEdges==0&&shell.Info.ClosedShells==1&&shell.Info.ContiguousEdges==12,"Six native faces failed closed box sewing");Check(Math.Abs(context.Inspect(shell.Shape).Volume-24)<1e-7,"Sewed closed shell volume differs from independent2x3x4 box");cases++;}finally{foreach(var face in faces)face.Dispose();}
  using(var solid=context.CreateBox(2,3,4)){var before=context.Inspect(solid);using var sewn=context.SewBreps(new[]{solid},.01);Check(sewn.Info.Faces==6&&sewn.Info.Parts==1&&sewn.Info.ClosedShells==1&&Math.Abs(context.Inspect(sewn.Shape).Volume-24)<1e-7,"Raw sewing dropped/filtered solid input");Check(context.Inspect(solid)==before,"Sewing mutated solid input");cases++;}
  using(var stream=typeof(SewingAssertions).Assembly.GetManifestResourceStream("RingRailLibraryFixture")!)using(var memory=new MemoryStream()){
   stream.CopyTo(memory);var document=LegacyCsg4Codec.Read(memory.ToArray());using var graph=new CandidateRailGraphSession(context,document,new(1e-7,1e-7,1e-7));
   foreach(bool edit in new[]{false,true}){if(edit){graph.Values.SetValue(2,document.Records[2].Scalar!.Value+.25);graph.Values.SetValue(136,.6);}graph.Generate(134,138,139);using var sweep=graph.RetainBrep(134);using var cap1=graph.RetainBrep(138);using var cap2=graph.RetainBrep(139);using var joined=context.SewBreps(new[]{sweep,cap1,cap2},.01);Check(context.Inspect(joined.Shape).IsValid,"Actual sew result invalid");Check(joined.Info.Parts==1&&joined.Info.Faces==3&&joined.Info.FreeEdges==0&&joined.Info.ClosedShells==1,"Actual sweep/caps did not form one closed native shell: "+joined.Info);cases++;
    var saved=LegacyCsg4Codec.Read(LegacyCsg4Codec.Write(graph.Values.ExportCurrentDocument()));using var loaded=new CandidateRailGraphSession(context,saved,new(1e-7,1e-7,1e-7));loaded.Generate(134,138,139);using var s=loaded.RetainBrep(134);using var a=loaded.RetainBrep(138);using var b=loaded.RetainBrep(139);using var reopened=context.SewBreps(new[]{s,a,b},.01);Check(reopened.Info==joined.Info,"Reopened native sewing topology differs");var oldBox=context.GetShapeBounds(joined.Shape,CandidateShapeBoundsMode.Accurate);var newBox=context.GetShapeBounds(reopened.Shape,CandidateShapeBoundsMode.Accurate);Check(Math.Abs(oldBox.Minimum.X-newBox.Minimum.X)<1e-8&&Math.Abs(oldBox.Maximum.Z-newBox.Maximum.Z)<1e-8&&Math.Abs(context.Inspect(joined.Shape).Volume-context.Inspect(reopened.Shape).Volume)<1e-7,"Reopened native sewing geometry differs");cases++;}
  }
  using(var face=Face(context,new(0,0,0),new(0,1,0),new(1,0,0),new(1,1,0))){ulong baseline=context.DiagnosticLiveShapeCount;Throws<ArgumentOutOfRangeException>(()=>context.SewBreps(Array.Empty<CandidateShape>(),.01));Throws<CandidateGeometryException>(()=>context.SewBreps(new[]{face},0));Throws<CandidateGeometryException>(()=>context.SewBreps(new[]{face},double.NaN));using(var foreign=CandidateContext.Create())Throws<ArgumentException>(()=>foreign.SewBreps(new[]{face},.01));using(var disposed=context.Clone(face)){disposed.Dispose();Throws<ObjectDisposedException>(()=>context.SewBreps(new[]{disposed},.01));}using(var line=context.CreateLine(new(0,0,0),new(1,0,0)))Throws<CandidateGeometryException>(()=>context.SewBreps(new[]{face,line},.01));Check(context.DiagnosticLiveShapeCount==baseline,"Failed sewing leaked native entries");}
  Check(context.DiagnosticLiveShapeCount==0,"Native sewing retained shape entries");return "PASS native BRep sewing:"+cases+" analytical/actual design cases; connected/free-edge/part diagnostics and copied inputs; source legacy join/repair/PC parity separate.";
 }
}
